BASELINE_SHA = 'e8127a0a5fc6aef84509de31908a745f5e59c81a2922ce3c624fb065557bd13e'
import ast
import base64
import hashlib
import io
import os
import shutil
import sys
import zipfile
from pathlib import Path

def die(message):
    raise SystemExit('ERROR: '+message)

def sha(b):
    return hashlib.sha256(b).hexdigest()

test, original = [Path(p).resolve(strict=True) for p in sys.argv[1:3]]
mode = sys.argv[3]
app = test/'app'
control = app/'format_control.py'
helper = app/'virtual_range.py'
media = app/'format_control_media'
parts = media/'virtual'
backup = test/'.nextory-virtual-range-baseline.py'
if test == original or test in original.parents or original in test.parents:
    die('Test and original overlap')
if any(p.is_symlink() for p in (app, control, helper, media, parts, backup)):
    die('Symlink in installation path')
if not control.is_file() or not media.is_dir() or not (media/'control.m4a').is_file():
    die('Playback format control A/B/C must be installed first')
if (original/'app/format_control.py').exists() or (original/'app/virtual_range.py').exists():
    die('Unexpected control source in original')
if 'NEXTORY_FORMAT_CONTROL_V1' not in (app/'main.py').read_text():
    die('Expected control route integration missing')
with zipfile.ZipFile(io.BytesIO(base64.b64decode(ARCHIVE))) as z:
    payload = {n:z.read(n) for n in z.namelist()}
if set(payload)!=set(EXPECTED) or any(sha(v)!=EXPECTED[n] for n,v in payload.items()):
    die('Embedded fixture integrity failure')
modified = payload.pop('format_control.py')
module = payload.pop('virtual_range.py')
for src in (modified, module):
    ast.parse(src)
for n in payload:
    if not n.startswith('format_control_media/virtual/') or '/' in n.removeprefix('format_control_media/virtual/') or '..' in Path(n).parts:
        die('Invalid fixture path')
current = control.read_bytes()
if sha(current) not in (BASELINE_SHA, sha(modified)):
    die('Format control source has unexpected modifications')
if backup.exists() and sha(backup.read_bytes()) != BASELINE_SHA:
    die('Existing backup integrity mismatch')

def assets_ok():
    if not helper.is_file() or helper.read_bytes()!=module or not parts.is_dir():
        return False
    actual = {}
    for p in parts.iterdir():
        if p.is_symlink() or not p.is_file():
            return False
        actual['format_control_media/virtual/'+p.name] = p.read_bytes()
    return actual==payload

def atomic_control(data):
    tmp = control.with_name('.virtual-range-control.tmp')
    if tmp.exists() or tmp.is_symlink():
        die('Unexpected temporary file')
    try:
        with tmp.open('xb') as f:
            f.write(data)
        tmp.chmod(control.stat().st_mode & 0o777)
        os.replace(tmp, control)
    finally:
        tmp.unlink(missing_ok=True)

if mode=='rollback':
    if not backup.is_file() or current!=modified or not assets_ok():
        die('Exact installed version not confirmed; rollback stopped')
    atomic_control(backup.read_bytes())
    helper.unlink()
    shutil.rmtree(parts)
    print('VIRTUAL_RANGE=REMOVED ABC=PRESERVED')
elif current==modified:
    if not backup.is_file() or not assets_ok():
        die('Installed fixture or backup differs')
    print('VIRTUAL_RANGE=ALREADY_ENABLED')
else:
    if helper.exists() or parts.exists():
        die('Unknown existing virtual range files')
    if not backup.exists():
        shutil.copy2(control, backup)
    try:
        helper.write_bytes(module)
        helper.chmod(0o644)
        parts.mkdir(mode=0o755)
        for n,b in payload.items():
            p=app/n
            p.write_bytes(b)
            p.chmod(0o644)
        if not assets_ok():
            raise RuntimeError('Fixture verification failed')
        atomic_control(modified)
    except BaseException:
        helper.unlink(missing_ok=True)
        if parts.exists():
            shutil.rmtree(parts)
        raise
    print('VIRTUAL_RANGE=ENABLED')
    print('FIXTURE=D_VIRTUAL_INDEXED_M4A')
print('NEXTORY_PROVIDER_AND_AUDIO=UNCHANGED')
print('PYTHON_SYNTAX=PASS')

PYCODE
echo
if [ "$OFFLINE" = 1 ]; then
  echo '=== 3. OFFLINE VERIFICATIE ==='
  echo 'SOURCE_PATCH=PASS'
  exit 0
fi

echo '=== 3. ALLEEN TESTCONTAINER HERBOUWEN ==='
docker compose -p "$PROJECT" -f "$TEST/docker-compose.yml" -f "$TEST/docker-compose.test.yml" \
  up -d --build --no-deps "$SERVICE"
echo
echo '=== 4. WACHTEN OP /HEALTH ==='
READY=0
for _ in $(seq 1 20); do
  if docker exec nextory-abs-poc-test python -c 'import urllib.request; assert urllib.request.urlopen("http://127.0.0.1:8000/health",timeout=3).status==200' >/dev/null 2>&1; then
    READY=1; break
  fi
  sleep 2
done
if [ "$READY" != 1 ]; then
  echo 'ERROR: Testcontainer reageert niet op /health. Geen automatische rollback: inspecteer eerst de toestand.'
  docker logs --tail 25 nextory-abs-poc-test 2>&1 | grep -E 'ERROR|Exception|Traceback|startup' | tail -12 || true
  exit 1
fi

echo '=== 5. CONTROLEREN ==='
docker exec -i nextory-abs-poc-test python - "$MODE" <<'PYVERIFY'
import json,sys,urllib.request
from app import main,format_control
headers={'Authorization':'Bearer '+main.make_token()}
req=urllib.request.Request('http://127.0.0.1:8000/api/libraries/'+format_control.LIBRARY_ID+'/items',headers=headers)
with urllib.request.urlopen(req,timeout=5) as r:
    books=json.load(r)
assert books['total']==(4 if sys.argv[1]=='apply' else 3)
if sys.argv[1]=='apply':
    from app.virtual_range import VirtualRange
    assert isinstance(format_control.VIRTUAL,VirtualRange)
    print('D_AVAILABLE=YES VIRTUAL_BYTES='+str(format_control.VIRTUAL.size))
else:
    assert not hasattr(format_control,'VIRTUAL')
    print('D_REMOVED=YES')
print('ABC_PRESERVED=YES')
PYVERIFY
docker inspect nextory-abs-poc-test --format 'TEST_RUNNING={{.State.Running}} HEALTH={{if .State.Health}}{{.State.Health.Status}}{{else}}unknown{{end}}'
docker inspect nextory-abs-poc --format 'ORIGINAL_RUNNING={{.State.Running}}'
echo '=== EINDE ==='
